`timescale 1ns/1ps
module tb_sync_fifo;
    reg clk;
    reg rst_n;
    reg wr_en;
    reg [7:0] wr_data;
    reg rd_en;
    wire [7:0] rd_data;
    wire full;
    wire empty;
    wire [3:0] count;

    sync_fifo dut (
        .clk(clk),
        .rst_n(rst_n),
        .wr_en(wr_en),
        .wr_data(wr_data),
        .rd_en(rd_en),
        .rd_data(rd_data),
        .full(full),
        .empty(empty),
        .count(count)
    );

    always #5 clk = ~clk;

    integer i;

    initial begin
        clk = 0;
        rst_n = 0;
        wr_en = 0;
        rd_en = 0;
        wr_data = 0;
        #20;
        rst_n = 1;
        #10;

        if (!empty || full || count !== 0) begin
            $display("FAIL: FIFO not empty on reset");
            $fatal(1);
        end

        for (i = 0; i < 8; i = i + 1) begin
            @(posedge clk);
            wr_en = 1;
            wr_data = 8'h10 + i;
        end
        @(posedge clk);
        wr_en = 0;
        #1;
        if (!full || empty || count !== 8) begin
            $display("FAIL: FIFO not full after 8 writes: full=%b empty=%b count=%0d", full, empty, count);
            $fatal(1);
        end

        @(posedge clk);
        wr_en = 1;
        wr_data = 8'hFF;
        @(posedge clk);
        wr_en = 0;
        #1;
        if (count !== 8) begin
            $display("FAIL: Overflow write modified count: %0d", count);
            $fatal(1);
        end

        for (i = 0; i < 8; i = i + 1) begin
            @(posedge clk);
            rd_en = 1;
            @(posedge clk);
            rd_en = 0;
            #1;
            if (rd_data !== (8'h10 + i)) begin
                $display("FAIL: Read mismatch at %0d: got %h expected %h", i, rd_data, 8'h10 + i);
                $fatal(1);
            end
        end

        if (!empty || full || count !== 0) begin
            $display("FAIL: FIFO not empty after 8 reads");
            $fatal(1);
        end

        $display("ALL_TESTS_PASSED");
        $finish;
    end
endmodule

sva_code:
module sync_fifo_formal(
    input wire clk,
    input wire rst_n,
    input wire wr_en,
    input wire [7:0] wr_data,
    input wire rd_en
);
    wire [7:0] rd_data;
    wire full, empty;
    wire [3:0] count;

    sync_fifo dut (
        .clk(clk),
        .rst_n(rst_n),
        .wr_en(wr_en),
        .wr_data(wr_data),
        .rd_en(rd_en),
        .rd_data(rd_data),
        .full(full),
        .empty(empty),
        .count(count)
    );

    always @(posedge clk) begin
        if (rst_n) begin
            assert(empty == (count == 0));
            assert(full == (count == 8));
            assert(!(full && empty));
            assert(count <= 8);
        end
    end
endmodule
